-- Easy Professions (Forever): guide texts in itIT (translated from wow-professions.com/forever)
local _, ns = ...
ns.AddTranslation("itIT", {
  ["This WoW Forever Alchemy leveling guide will show you the fastest and cheapest way to level your Alchemy skill from 1 to 300. You will also find every trainer location and where to train Alchemy past 75, 150 and 225."] = "Questa guida per salire di livello in Alchimia su WoW Forever ti mostra il modo più rapido ed economico per portare la tua abilità di Alchimia da 1 a 300. Troverai anche la posizione di ogni istruttore e dove imparare l'Alchimia oltre 75, 150 e 225.",
  ["Below you will find the full shopping list, the Alchemy trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Alchemy is best combined with Herbalism, with these two you can save a lot of gold because you don't have to buy the herbs from the Auction House."] = "Qui sotto trovi la lista della spesa completa, gli istruttori di Alchimia per zona iniziale e capitale, e le ricette più economiche per ogni fascia di abilità da Apprendista ad Artigiano. L'Alchimia si abbina meglio all'Erbalismo: con queste due risparmi un sacco d'oro perché non devi comprare le erbe alla casa d'aste.",
  ["This is based on the Forever beta. Leveling takes a long time, so testing the higher levels on live will take a while. If you find something that's off, send me feedback."] = "La guida si basa sulla beta di Forever. Salire di livello richiede molto tempo, quindi testare i livelli più alti sul server live richiederà un po'. Se trovi qualcosa che non va, mandami un feedback.",
  ["Shopping List"] = "Lista della spesa",
  ["These numbers are estimates. Once a recipe turns yellow you won't get a skill point from every craft, so you might need a few more or a few less."] = "Questi numeri sono stime. Quando una ricetta diventa gialla non otterrai un punto abilità a ogni creazione, quindi potresti averne bisogno di qualcuno in più o in meno.",
  ["Alchemy Trainer Locations"] = "Posizione degli istruttori di Alchimia",
  ["Apprentice Alchemy has no level requirement in Forever, so you can learn it on a fresh character."] = "L'Alchimia Apprendista non ha requisiti di livello su Forever, quindi puoi impararla con un personaggio appena creato.",
  ["Every capital city has a trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "Ogni capitale ha un istruttore. Puoi anche chiedere a una guardia: verrà segnato con una bandierina rossa sulla mappa.",
  ["Horde"] = "Orda",
  ["Alliance"] = "Alleanza",
  ["Capital Cities"] = "Capitali",
  ["Undercity: {n:0:horde:Doctor Martin Felben}"] = "Sepulcride: {n:0:horde:Doctor Martin Felben}",
  ["Thunder Bluff: {n:0:horde:Kray}"] = "Picco del Tuono: {n:0:horde:Kray}",
  ["Starting Zones"] = "Zone iniziali",
  ["Not every zone has a trainer, the table shows the closest one for each race."] = "Non tutte le zone hanno un istruttore, la tabella mostra quello più vicino per ogni razza.",
  ["Race"] = "Razza",
  ["Zone"] = "Zona",
  ["Closest trainer"] = "Istruttore più vicino",
  ["Orc, Troll"] = "Orco, Troll",
  ["{n:0:horde:Miao'zan} in Sen'jin Village"] = "{n:0:horde:Miao'zan} nel Villaggio di Sen'jin",
  ["There is no Alchemy trainer in Mulgore, go to {n:0:horde:Kray} on the middle rise in Thunder Bluff"] = "Non c'è un istruttore di Alchimia a Mulgore, vai da {n:0:horde:Kray} sull'altura centrale di Picco del Tuono",
  ["Undead"] = "Non Morto",
  ["Tirisfal Glades"] = "Radure di Tirisfal",
  ["{n:0:horde:Carolai Anise} in the small house at the north-west end of Brill"] = "{n:0:horde:Carolai Anise} nella casetta all'estremità nord-ovest di Brill",
  ["Zephras Isle"] = "Isola di Zephras",
  ["{n:0::Iaadaria Bitterwind} or {n:0::Valiena Swiftgale} in Valanaar, {n:0::Nyassa Swiftdraught} in Shen'dar Village"] = "{n:0::Iaadaria Bitterwind} o {n:0::Valiena Swiftgale} a Valanaar, {n:0::Nyassa Swiftdraught} nel Villaggio di Shen'dar",
  ["Stormwind City: {n:0:alliance:Tel'Athir}"] = "Roccavento: {n:0:alliance:Tel'Athir}",
  ["Ironforge: {n:0:alliance:Vosur Brakthel}"] = "Forgiardente: {n:0:alliance:Vosur Brakthel}",
  ["Human"] = "Umano",
  ["Elwynn Forest"] = "Foresta di Elwynn",
  ["{n:0:alliance:Alchemist Mallory} in a cottage in the hills between Stormwind and Northshire"] = "{n:0:alliance:Alchemist Mallory} in una casetta sulle colline tra Roccavento e Contea del Nord",
  ["Dwarf, Gnome"] = "Nano, Gnomo",
  ["There is no Alchemy trainer in Dun Morogh, go to {n:0:alliance:Vosur Brakthel} in Tinker Town in Ironforge"] = "Non c'è un istruttore di Alchimia a Dun Morogh, vai da {n:0:alliance:Vosur Brakthel} nel Borgo degli Inventori a Forgiardente",
  ["Night Elf"] = "Elfo della Notte",
  ["{n:0:alliance:Cyndra Kindwhisper} in a small house east of the inn in Dolanaar"] = "{n:0:alliance:Cyndra Kindwhisper} in una casetta a est della locanda di Dolanaar",
  ["You can find every Alchemy trainer for Horde and Alliance on my WoW Forever Alchemy Trainers page."] = "Puoi trovare tutti gli istruttori di Alchimia dell'Orda e dell'Alleanza nella mia pagina WoW Forever Alchemy Trainers.",
  ["Apprentice Alchemy (1-55)"] = "Alchimia Apprendista (1-55)",
  ["9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Silverleaf, 9 Empty Vial"] = "9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Fogliargento, 9 Fiala Vuota",
  ["The vials are sold by Alchemy Supply and Trade Supply vendors, most trainers have one nearby. In Undercity the closest one is {n:0:horde:Algernon}, in Dolanaar it's {n:0:alliance:Narret Shadowgrove}."] = "Le fiale sono vendute dai mercanti di forniture alchemiche e di articoli commerciali, la maggior parte degli istruttori ne ha uno vicino. A Sepulcride il più vicino è {n:0:horde:Algernon}, a Dolanaar è {n:0:alliance:Narret Shadowgrove}.",
  ["45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Silverleaf, 45 Peacebloom, 45 Empty Vial"] = "45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Fogliargento, 45 Sbocciapace, 45 Fiala Vuota",
  ["Journeyman Alchemy (55-150)"] = "Alchimia Garzone (55-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Alchemy. You need {b}Alchemy 50{/b} and {b}level 10{/b}:"] = "Per andare oltre 75, visita uno di questi istruttori e impara il grado Garzone di Alchimia. Ti servono {b}Alchimia 50{/b} e {b}livello 10{/b}:",
  ["{b}Horde trainers:{/b}"] = "{b}Istruttori dell'Orda:{/b}",
  ["Undercity: {n:0:horde:Doctor Marsh}"] = "Sepulcride: {n:0:horde:Doctor Marsh}",
  ["Thunder Bluff: {n:0:horde:Bena Winterhoof}"] = "Picco del Tuono: {n:0:horde:Bena Winterhoof}",
  ["{b}Alliance trainers:{/b}"] = "{b}Istruttori dell'Alleanza:{/b}",
  ["Stormwind City: {n:0:alliance:Lilyssia Nightbreeze}"] = "Roccavento: {n:0:alliance:Lilyssia Nightbreeze}",
  ["Ironforge: {n:0:alliance:Tally Berryfizz}"] = "Forgiardente: {n:0:alliance:Tally Berryfizz}",
  ["10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Mageroyal, 10 Peacebloom, 10 Empty Vial"] = "10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Magoreale, 10 Sbocciapace, 10 Fiala Vuota",
  ["28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Earthroot, 28 Peacebloom, 28 Empty Vial"] = "28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Radiceterra, 28 Sbocciapace, 28 Fiala Vuota",
  ["30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Mageroyal, 60 Briarthorn, 30 Empty Vial"] = "30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Magoreale, 60 Briarthorn, 30 Fiala Vuota",
  ["Keep the elixirs if you also level Tailoring, you will need them for the Gloves of Meditation."] = "Tieni gli elisir se sali anche in Sartoria, ti serviranno per i Gloves of Meditation.",
  ["10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Mageroyal, 10 Stranglekelp, 10 Empty Vial"] = "10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Magoreale, 10 Stranglekelp, 10 Fiala Vuota",
  ["20x {s:7837:inv_potion_38:Fire Oil} - 40 Firefin Snapper, 20 Empty Vial"] = "20x {s:7837:inv_potion_38:Fire Oil} - 40 Firefin Snapper, 20 Fiala Vuota",
  ["You get 2 oils from every craft. Keep 30 of them, you will need them for the Elixir of Fire Power in the next part."] = "Ottieni 2 oli da ogni creazione. Tienine 30, ti serviranno per l'Elixir of Fire Power nella parte successiva.",
  ["Expert Alchemy (150-225)"] = "Alchimia Esperto (150-225)",
  ["To train past 150, visit {n:0:horde:Doctor Herbert Halsey} in Undercity (Horde) or {n:0:alliance:Ainethil} in Darnassus (Alliance) and learn Expert Alchemy. You need {b}Alchemy 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "Per andare oltre 150, visita {n:0:horde:Doctor Herbert Halsey} a Sepulcride (Orda) o {n:0:alliance:Ainethil} a Darnassus (Alleanza) e impara il grado Esperto di Alchimia. Ti servono {b}Alchimia 125{/b} e {b}livello 20{/b}, e costa 50 argento.",
  ["15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Fire Oil, 15 Kingsblood, 15 Leaded Vial"] = "15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Fire Oil, 15 Kingsblood, 15 Fiala Piombata",
  ["These are the Fire Oils you kept."] = "Questi sono i Fire Oil che hai tenuto.",
  ["36x {s:3452:inv_potion_72:Mana Potion} - 36 Stranglekelp, 36 Kingsblood, 36 Leaded Vial"] = "36x {s:3452:inv_potion_72:Mana Potion} - 36 Stranglekelp, 36 Kingsblood, 36 Fiala Piombata",
  ["36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Liferoot, 36 Stranglekelp, 36 Leaded Vial"] = "36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Liferoot, 36 Stranglekelp, 36 Fiala Piombata",
  ["{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} is sold by these vendors, it's bind on pickup, so buy it with the character that levels Alchemy:"] = "{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} è venduta da questi mercanti; è vincolata alla raccolta, quindi comprala con il personaggio che sale in Alchimia:",
  ["{n:0:horde:Bronk} in Feralas"] = "{n:0:horde:Bronk} a Feralas",
  ["{n:0:alliance:Logannas} in Feralas"] = "{n:0:alliance:Logannas} a Feralas",
  ["{n:0::Glyx Brewright} in Stranglethorn Vale"] = "{n:0::Glyx Brewright} nella Valle di Rovotorto",
  ["{n:0::Alchemist Pestlezugg} in Tanaris"] = "{n:0::Alchemist Pestlezugg} a Tanaris",
  ["Artisan Alchemy (225-300)"] = "Alchimia Artigiano (225-300)",
  ["To train past 225, visit {n:0:horde:Rogvar} in Stonard, Swamp of Sorrows (Horde) or {n:0:alliance:Kylanna Windwhisper} in Feathermoon Stronghold, Feralas (Alliance) and learn Artisan Alchemy. You need {b}Alchemy 200{/b} and {b}level 35{/b}."] = "Per andare oltre 225, visita {n:0:horde:Rogvar} a Stonard, Palude del Dolore (Orda) o {n:0:alliance:Kylanna Windwhisper} a Feathermoon Stronghold, Feralas (Alleanza) e impara il grado Artigiano di Alchimia. Ti servono {b}Alchimia 200{/b} e {b}livello 35{/b}.",
  ["26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Liferoot, 26 Stranglekelp, 26 Leaded Vial"] = "26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Liferoot, 26 Stranglekelp, 26 Fiala Piombata",
  ["15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Blindweed, 15 Khadgar's Whisker, 15 Crystal Vial"] = "15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Blindweed, 15 Khadgar's Whisker, 15 Fiala di Cristallo",
  ["47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Stonescale Eel, 47 Leaded Vial"] = "47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Stonescale Eel, 47 Fiala Piombata",
  ["{b}Keep all of them{/b}, one craft makes 2 and the elixirs at 265 need all 94."] = "{b}Tienili tutti{/b}: ogni creazione ne produce 2 e gli elisir a 265 li richiedono tutti e 94.",
  ["Alternative recipe"] = "Ricetta alternativa",
  ["If {i:13422:inv_misc_fish_11:Stonescale Eel} is expensive, skip this and keep making the Elixir of Greater Intellect until 265 (about 21), then make the Superior Mana Potions under 265-300."] = "Se {i:13422:inv_misc_fish_11:Stonescale Eel} costa troppo, salta questo passaggio e continua a creare l'Elixir of Greater Intellect fino a 265 (circa 21), poi crea le Superior Mana Potion indicate in 265-300.",
  ["10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Blindweed, 10 Khadgar's Whisker, 10 Crystal Vial"] = "10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Blindweed, 10 Khadgar's Whisker, 10 Fiala di Cristallo",
  ["47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Stonescale Oil, 47 Sungrass, 47 Crystal Vial"] = "47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Stonescale Oil, 47 Sungrass, 47 Fiala di Cristallo",
  ["{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} is sold by {n:0:horde:Kor'geld} in Orgrimmar and {n:0:alliance:Soolie Berryfizz} in Ironforge."] = "{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} è venduta da {n:0:horde:Kor'geld} a Orgrimmar e da {n:0:alliance:Soolie Berryfizz} a Forgiardente.",
  ["If you skipped the Stonescale Oil, make this:"] = "Se hai saltato lo Stonescale Oil, crea questo:",
  ["55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Sungrass, 110 Blindweed, 55 Crystal Vial."] = "55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Sungrass, 110 Blindweed, 55 Fiala di Cristallo.",
  ["{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} is sold by {n:0:horde:Algernon} in Undercity and {n:0:alliance:Ulthir} in Darnassus."] = "{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} è venduta da {n:0:horde:Algernon} a Sepulcride e da {n:0:alliance:Ulthir} a Darnassus.",
  ["This WoW Forever Blacksmithing leveling guide will show you the fastest and cheapest way to level your Blacksmithing skill from 1 to 300. You will also find every trainer location and where to train Blacksmithing past 75, 150 and 225."] = "Questa guida per salire di livello in Forgiatura su WoW Forever ti mostra il modo più rapido ed economico per portare la tua abilità di Forgiatura da 1 a 300. Troverai anche la posizione di ogni istruttore e dove imparare la Forgiatura oltre 75, 150 e 225.",
  ["Below you will find the full shopping list, the Blacksmithing trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Blacksmithing uses a lot of ore, so I recommend leveling it together with Mining, you will need a lot of gold if you want to buy everything from the Auction House."] = "Qui sotto trovi la lista della spesa completa, gli istruttori di Forgiatura per zona iniziale e capitale, e le ricette più economiche per ogni fascia di abilità da Apprendista ad Artigiano. La Forgiatura richiede molto minerale, quindi ti consiglio di salirla insieme all'Estrazione: ti servirà un sacco d'oro se vuoi comprare tutto alla casa d'aste.",
  ["The Thorium Bars include the 140 you need for the four quests."] = "Le Barre di Torio includono le 140 che ti servono per le quattro missioni.",
  ["Blacksmithing Trainer Locations"] = "Posizione degli istruttori di Forgiatura",
  ["Apprentice Blacksmithing has no level requirement in Forever, so you can learn it on a fresh character."] = "La Forgiatura Apprendista non ha requisiti di livello su Forever, quindi puoi impararla con un personaggio appena creato.",
  ["Every capital city has a trainer except Darnassus. You can also ask a guard, then it will be marked with a red flag on your map."] = "Ogni capitale tranne Darnassus ha un istruttore. Puoi anche chiedere a una guardia: verrà segnato con una bandierina rossa sulla mappa.",
  ["Undercity: {n:0:horde:Basil Frye}"] = "Sepulcride: {n:0:horde:Basil Frye}",
  ["Thunder Bluff: {n:0:horde:Thrag Stonehoof}"] = "Picco del Tuono: {n:0:horde:Thrag Stonehoof}",
  ["{n:0:horde:Dwukk} at the forge in Razor Hill"] = "{n:0:horde:Dwukk} alla forgia di Razor Hill",
  ["There is no Blacksmithing trainer in Mulgore, go to {n:0:horde:Thrag Stonehoof} on the lower rise in Thunder Bluff"] = "Non c'è un istruttore di Forgiatura a Mulgore, vai da {n:0:horde:Thrag Stonehoof} sull'altura inferiore di Picco del Tuono",
  ["{n:0:horde:Angus Hammerhand} at Bandarion Keep. Nobody near him sells a {i:5956:inv_hammer_20:Blacksmith Hammer}, {b}buy one before you go{/b} from {n:0:horde:Walter Mason} in Deathknell or {n:0:horde:Abigail Shiel} in Brill."] = "{n:0:horde:Angus Hammerhand} a Bandarion Keep. Nessuno vicino a lui vende il {i:5956:inv_hammer_20:Blacksmith Hammer}, {b}compralo prima di andare{/b} da {n:0:horde:Walter Mason} a Deathknell o da {n:0:horde:Abigail Shiel} a Brill.",
  ["{n:0::Daeann Steelwind} in Valanaar, {n:0::Aedi Thriceforged} in Shen'dar Village"] = "{n:0::Daeann Steelwind} a Valanaar, {n:0::Aedi Thriceforged} nel Villaggio di Shen'dar",
  ["Stormwind City: {n:0:alliance:Dane Lindgren}"] = "Roccavento: {n:0:alliance:Dane Lindgren}",
  ["Ironforge: {n:0:alliance:Groum Stonebeard}"] = "Forgiardente: {n:0:alliance:Groum Stonebeard}",
  ["{n:0:alliance:Smith Argus} in Goldshire, across from the inn"] = "{n:0:alliance:Smith Argus} a Goldshire, di fronte alla locanda",
  ["{n:0:alliance:Tognus Flintfire} in Kharanos, across from the Thunderbrew Distillery"] = "{n:0:alliance:Tognus Flintfire} a Kharanos, di fronte alla Distilleria Tuonabirra",
  ["There is no Blacksmithing trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Delfrum Flintbeard} in Auberdine, Darkshore"] = "Non c'è un istruttore di Forgiatura a Teldrassil o a Darnassus, il più vicino è {n:0:alliance:Delfrum Flintbeard} ad Auberdine, Rivafosca",
  ["You can find every Blacksmithing trainer for Horde and Alliance on my WoW Forever Blacksmithing Trainers page."] = "Puoi trovare tutti gli istruttori di Forgiatura dell'Orda e dell'Alleanza nella mia pagina WoW Forever Blacksmithing Trainers.",
  ["Apprentice Blacksmithing (1-75)"] = "Forgiatura Apprendista (1-75)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer} when you learn Blacksmithing, most recipes need it, so you can craft gear for yourself while you level. It costs a few copper, open your faction below to see who sells it closest to your trainer."] = "Compra un {i:5956:inv_hammer_20:Blacksmith Hammer} quando impari la Forgiatura: serve per la maggior parte delle ricette, così puoi creare equipaggiamento per te mentre sali. Costa pochi rame, apri la tua fazione qui sotto per vedere chi lo vende più vicino al tuo istruttore.",
  ["Horde vendors"] = "Mercanti dell'Orda",
  ["Vendor"] = "Mercante",
  ["{n:0:horde:Sumi}, right next to the trainer"] = "{n:0:horde:Sumi}, proprio accanto all'istruttore",
  ["Undercity"] = "Sepulcride",
  ["{n:0:horde:Samuel Van Brunt}, right next to the trainer"] = "{n:0:horde:Samuel Van Brunt}, proprio accanto all'istruttore",
  ["Thunder Bluff"] = "Picco del Tuono",
  ["{n:0:horde:Taur Stonehoof}, right next to the trainer"] = "{n:0:horde:Taur Stonehoof}, proprio accanto all'istruttore",
  ["{n:0:horde:Flakk} in Razor Hill"] = "{n:0:horde:Flakk} a Razor Hill",
  ["{n:0:horde:Walter Mason} in Deathknell {n:0:horde:Abigail Shiel} in Brill"] = "{n:0:horde:Walter Mason} a Deathknell {n:0:horde:Abigail Shiel} a Brill",
  ["{n:0::Halavuul Cragwind}, the Mining trainer in Valanaar {n:0::Aedi Thriceforged} in Shen'dar Village"] = "{n:0::Halavuul Cragwind}, l'istruttore di Estrazione a Valanaar {n:0::Aedi Thriceforged} nel Villaggio di Shen'dar",
  ["Alliance vendors"] = "Mercanti dell'Alleanza",
  ["Stormwind City"] = "Roccavento",
  ["{n:0:alliance:Kaita Deepforge}, right next to the trainer"] = "{n:0:alliance:Kaita Deepforge}, proprio accanto all'istruttore",
  ["Ironforge"] = "Forgiardente",
  ["{n:0:alliance:Thurgrum Deepforge}, right next to the trainer"] = "{n:0:alliance:Thurgrum Deepforge}, proprio accanto all'istruttore",
  ["{n:0:alliance:Tharynn Bouden} in Goldshire"] = "{n:0:alliance:Tharynn Bouden} a Goldshire",
  ["{n:0:alliance:Thrawn Boltar}, right next to the trainer"] = "{n:0:alliance:Thrawn Boltar}, proprio accanto all'istruttore",
  ["Darkshore"] = "Rivafosca",
  ["{n:0:alliance:Elisa Steelhand} in Auberdine, right next to the trainer"] = "{n:0:alliance:Elisa Steelhand} ad Auberdine, proprio accanto all'istruttore",
  ["30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Rough Stone"] = "30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Pietra Grezza",
  ["30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Rough Stone"] = "30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Pietra Grezza",
  ["Keep 10 of them, you need them for the Silver Rods at 75."] = "Tienine 10, ti servono per le Silver Rod a 75.",
  ["36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Coarse Stone"] = "36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Pietra Grossolana",
  ["Make all 36, you will need them for the bracers at 95 and 112."] = "Creale tutte e 36, ti serviranno per i bracciali a 95 e 112.",
  ["If you are not at 75 after these, make a few more."] = "Se dopo queste non sei a 75, creane qualcuna in più.",
  ["Journeyman Blacksmithing (75-150)"] = "Forgiatura Garzone (75-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Blacksmithing. You need {b}Blacksmithing 50{/b} and {b}level 10{/b}:"] = "Per andare oltre 75, visita uno di questi istruttori e impara il grado Garzone di Forgiatura. Ti servono {b}Forgiatura 50{/b} e {b}livello 10{/b}:",
  ["Undercity: {n:0:horde:James Van Brunt}"] = "Sepulcride: {n:0:horde:James Van Brunt}",
